import{c as r,Q as d,j as o,m as n}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-网络与安全-信息安全基础","description":"","frontmatter":{"title":"架构师-备考 综合知识-网络与安全-信息安全基础"},"headers":[],"relativePath":"综合知识/网络与安全/信息安全基础.md","filePath":"综合知识/网络与安全/信息安全基础.md","lastUpdated":null}'),a={name:"综合知识/网络与安全/信息安全基础.md"};function s(e,t,g,h,l,b){return d(),o("div",null,[...t[0]||(t[0]=[n('<h3 id="信息安全-5-要素" tabindex="-1">信息安全 5 要素 <a class="header-anchor" href="#信息安全-5-要素" aria-label="Permalink to &quot;信息安全 5 要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>关键词</th></tr></thead><tbody><tr><td><strong>机密性</strong></td><td>确保信息不暴露给未授权实体或进程</td><td>不泄露</td></tr><tr><td><strong>完整性</strong></td><td>只有授权者才能修改数据，能判别数据是否被篡改</td><td>防篡改</td></tr><tr><td><strong>可用性</strong></td><td>授权实体在需要时可访问数据</td><td>能访问</td></tr><tr><td><strong>可控性</strong></td><td>控制授权范围内的信息流向及行为方式</td><td>能控制</td></tr><tr><td><strong>可审查性</strong></td><td>对信息安全问题提供调查依据和手段</td><td>可追溯</td></tr></tbody></table><blockquote><p>完整的信息安全系统包含三类措施：<strong>技术措施 + 管理措施 + 政策法律</strong>。</p></blockquote><hr><h3 id="信息安全范围" tabindex="-1">信息安全范围 <a class="header-anchor" href="#信息安全范围" aria-label="Permalink to &quot;信息安全范围&quot;">​</a></h3><table tabindex="0"><thead><tr><th>范围</th><th>说明</th><th>三方面</th></tr></thead><tbody><tr><td><strong>设备安全</strong></td><td>信息系统安全的<strong>首要问题</strong>和物质基础</td><td>稳定性、可靠性、可用性</td></tr><tr><td><strong>数据安全</strong></td><td>确保数据免受未授权泄露/篡改/毁坏</td><td>秘密性、完整性、可用性</td></tr><tr><td><strong>内容安全</strong></td><td>政治/法律/道德层次要求</td><td>政治上健康、合法合规、道德规范</td></tr><tr><td><strong>行为安全</strong></td><td>最终通过行为提供给用户</td><td>秘密性、完整性、可控性</td></tr></tbody></table><p><strong>存储安全</strong>：信息使用安全（用户标识验证/存取权限）、系统安全监控（审计/日志）、计算机病毒防治、数据加密和防非法攻击。</p><p><strong>网络安全隐患</strong>：物理安全性、软件安全漏洞、不兼容使用安全漏洞、选择合适的安全哲理。</p><p><strong>网络安全威胁</strong>：非授权访问、信息泄露或丢失、破坏数据完整性、拒绝服务攻击、利用网络传播病毒。</p><hr><h3 id="加密技术" tabindex="-1">加密技术 <a class="header-anchor" href="#加密技术" aria-label="Permalink to &quot;加密技术&quot;">​</a></h3><h4 id="密码体制-5-组成" tabindex="-1">密码体制 5 组成 <a class="header-anchor" href="#密码体制-5-组成" aria-label="Permalink to &quot;密码体制 5 组成&quot;">​</a></h4><p>明文空间 M → 加密算法 E（使用密钥 Ke）→ 密文空间 C → 解密算法 D（使用密钥 Kd）→ 明文 M</p><h4 id="对称-vs-非对称对比" tabindex="-1">对称 vs 非对称对比 <a class="header-anchor" href="#对称-vs-非对称对比" aria-label="Permalink to &quot;对称 vs 非对称对比&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比维度</th><th>对称加密</th><th>非对称加密</th></tr></thead><tbody><tr><td><strong>密钥</strong></td><td>加密解密<strong>密钥相同</strong></td><td>加密解密<strong>密钥不同</strong>（公钥+私钥）</td></tr><tr><td><strong>密钥位数</strong></td><td>56位（DES）</td><td>512/1024位（RSA）</td></tr><tr><td><strong>加密速度</strong></td><td><strong>快</strong></td><td>慢</td></tr><tr><td><strong>安全性</strong></td><td>较低（密钥位数少）</td><td><strong>高</strong>，难破解</td></tr><tr><td><strong>密钥分发</strong></td><td>困难</td><td>容易（公钥公开）</td></tr><tr><td><strong>适用场景</strong></td><td>加密大数据</td><td>加密对称密钥</td></tr><tr><td><strong>算法</strong></td><td>DES/3DES/AES/RC-5/IDEA</td><td>RSA/Elgamal/ECC/D-H</td></tr></tbody></table><p><strong>常见对称算法：</strong></p><table tabindex="0"><thead><tr><th>算法</th><th>特点</th></tr></thead><tbody><tr><td><strong>DES</strong></td><td>替换+移位，56位密钥，64位数据块</td></tr><tr><td><strong>3DES</strong></td><td>两个56位密钥 K1/K2，加密：K1加密→K2解密→K1加密</td></tr><tr><td><strong>AES</strong></td><td>替代 DES 的区块加密标准，至少像 3DES 一样安全</td></tr><tr><td><strong>RC-5</strong></td><td>RSA 公司产品常用</td></tr><tr><td><strong>IDEA</strong></td><td>128位密钥，64位数据块，比 DES 加密性好</td></tr></tbody></table><p><strong>常见非对称算法：</strong> RSA（512/1024位）、Elgamal、ECC（椭圆曲线）、背包算法、Rabin、D-H。</p><hr><h3 id="数字信封" tabindex="-1">数字信封 <a class="header-anchor" href="#数字信封" aria-label="Permalink to &quot;数字信封&quot;">​</a></h3><blockquote><p>本质：<strong>对称密钥加密数据 + 非对称密钥加密对称密钥</strong>，解决对称密钥传输问题。</p></blockquote><p>过程：发送方→数据用<strong>对称密钥</strong>加密传输 → 对称密钥用<strong>接收方公钥</strong>加密（形成数字信封）→ 接收方用自己的私钥解密信封取出对称密钥 → 解密数据。</p><hr><h3 id="信息摘要与数字签名" tabindex="-1">信息摘要与数字签名 <a class="header-anchor" href="#信息摘要与数字签名" aria-label="Permalink to &quot;信息摘要与数字签名&quot;">​</a></h3><h4 id="信息摘要" tabindex="-1">信息摘要 <a class="header-anchor" href="#信息摘要" aria-label="Permalink to &quot;信息摘要&quot;">​</a></h4><blockquote><p>一段数据的特征信息，由<strong>哈希函数</strong>生成。数据改变则摘要改变。</p></blockquote><p><strong>特点</strong>：固定长度输出、不同输入不同摘要、<strong>单向性</strong>（只能由数据生成摘要，不能还原）。</p><table tabindex="0"><thead><tr><th>算法</th><th style="text-align:center;">输出位数</th></tr></thead><tbody><tr><td><strong>MD5</strong></td><td style="text-align:center;">128位</td></tr><tr><td><strong>SHA-1</strong></td><td style="text-align:center;">160位（安全性更高）</td></tr></tbody></table><h4 id="数字签名" tabindex="-1">数字签名 <a class="header-anchor" href="#数字签名" aria-label="Permalink to &quot;数字签名&quot;">​</a></h4><blockquote><p>唯一标识一个发送方。发送方用<strong>自己的私钥</strong>加密 → 接收方用<strong>发送方的公钥</strong>解密。保证<strong>完整性</strong>和身份认证，阻止抵赖，但<strong>不保证机密性</strong>。</p></blockquote><p><strong>对比速记：</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>密钥使用</th><th>保证</th></tr></thead><tbody><tr><td><strong>加密通信</strong></td><td>用<strong>接收方公钥</strong>加密</td><td>机密性</td></tr><tr><td><strong>数字签名</strong></td><td>用<strong>发送方私钥</strong>加密</td><td>完整性+身份认证</td></tr></tbody></table><hr><h3 id="pki-体系" tabindex="-1">PKI 体系 <a class="header-anchor" href="#pki-体系" aria-label="Permalink to &quot;PKI 体系&quot;">​</a></h3><blockquote><p>PKI（公钥基础设施）：以<strong>不对称密钥加密技术为基础</strong>，以机密性、完整性、身份认证和不可抵赖为安全目的。</p></blockquote><p><strong>数字证书（X.509）</strong>：由可信权威机构签署的信息集合，包含版本号、序列号、签名算法、认证机构、有效期限、主题信息、CA数字签名、公钥信息。<strong>确保公钥及其与用户绑定关系的安全</strong>。如驾照。</p><p><strong>CA（签证机构）</strong>：负责签发、管理和撤销证书。签发证书时加上自己的<strong>数字签名</strong>保证真实性。任何机构可用 CA 的公钥验证证书合法性。</p><blockquote><p><strong>Kerberos vs PKI</strong>：第三方认证服务的两种体制。Kerberos 基于信任第三方，KDC 保存密钥；PKI 基于证书，CA 保存数字证书。Kerberos ≠ 公钥基础设施。</p></blockquote><hr><h3 id="访问控制" tabindex="-1">访问控制 <a class="header-anchor" href="#访问控制" aria-label="Permalink to &quot;访问控制&quot;">​</a></h3><blockquote><p>三要素：主体、客体、控制策略。包括认证、控制策略实现、审计。</p></blockquote><p><strong>四种实现技术：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>方式</th><th>特点</th></tr></thead><tbody><tr><td><strong>访问控制矩阵（ACM）</strong></td><td>主体为行，客体为列</td><td>矩阵形式表示权限</td></tr><tr><td><strong>访问控制表（ACL）</strong></td><td><strong>按列保存</strong>访问矩阵</td><td>每个客体有一张表，<strong>最流行最常用</strong></td></tr><tr><td><strong>能力表</strong></td><td><strong>按行保存</strong>访问矩阵</td><td>每个主体有一张表，方便查询该主体所有权限</td></tr><tr><td><strong>授权关系表</strong></td><td>每一行是矩阵中一个非空元素</td><td>按主体排序=能力表效率，按客体排序=ACL效率</td></tr></tbody></table><hr><h3 id="信息安全技术体系" tabindex="-1">信息安全技术体系 <a class="header-anchor" href="#信息安全技术体系" aria-label="Permalink to &quot;信息安全技术体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层面</th><th>说明</th></tr></thead><tbody><tr><td><strong>基础安全设备</strong></td><td>密码芯片、加密卡、身份识别卡 + 物理安全</td></tr><tr><td><strong>计算机网络安全</strong></td><td>信息网络传输安全防范（物理隔离/防火墙/加密传输/认证/VPN/病毒防范/安全审计）</td></tr><tr><td><strong>操作系统安全</strong></td><td>无错误配置、无漏洞、无后门、无特洛伊木马（标识鉴别/访问控制/最小特权/可信通路/存储保护/文件保护/安全审计）</td></tr><tr><td><strong>数据库安全</strong></td><td>DBMS安全+数据库应用系统安全（物理完整性/逻辑完整性/元素安全/可审计/访问控制/推理控制/多级保护）</td></tr><tr><td><strong>终端安全设备</strong></td><td>电话密码机、传真密码机、异步数据密码机</td></tr></tbody></table><hr><h3 id="安全保护等级-gb17859" tabindex="-1">安全保护等级（GB17859） <a class="header-anchor" href="#安全保护等级-gb17859" aria-label="Permalink to &quot;安全保护等级（GB17859）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>名称</th><th>关键特征</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td>用户自主保护级</td><td>隔离用户与数据，自主访问控制</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td>系统审计保护级</td><td>粒度更细的自主访问控制，登录规程+审计+资源隔离</td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td>安全标记保护级</td><td>安全策略模型+数据标记，<strong>强制访问控制</strong></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td>结构化保护级</td><td>明确定义的形式化安全策略模型，扩展至所有主体与客体，考虑隐蔽通道</td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td>访问验证保护级</td><td>满足<strong>访问监控器</strong>需求，抗篡改，足够小可分析测试</td></tr></tbody></table><hr><h3 id="安全风险管理" tabindex="-1">安全风险管理 <a class="header-anchor" href="#安全风险管理" aria-label="Permalink to &quot;安全风险管理&quot;">​</a></h3><p><strong>风险评估实施前应考虑</strong>：确定范围 → 确定目标 → 建立组织结构 → 建立系统性评估方法 → 获得最高管理者批准。</p><p><strong>风险评估基本要素</strong>：脆弱性、资产、威胁、风险、安全措施。相关属性：业务战略、资产价值、安全需求、安全事件、残余风险。</p><p><strong>风险计算过程</strong>：识别资产并赋值 → 分析威胁并赋值可能性 → 识别脆弱性并赋值严重程度 → 计算安全事件可能性 → 计算风险值。</p>',54)])])}const p=r(a,[["render",s]]);export{c as __pageData,p as default};
